"""Rebuild the checked-in foundations course and its Docker acceptance solutions."""
import json
from pathlib import Path
import sys
import shlex

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "backend"))
from lab.schema import Course, course_yaml

ROOT = Path(__file__).resolve().parents[1]
exercises, solutions = [], {}


def add(id, title, description, tasks, tips, solution, setup=None):
    exercises.append(dict(id=id, title=title, description=description, tasks=[dict(id=f"task-{i+1}", description=text, points=5, checks=checks) for i, (text, checks) in enumerate(tasks)], tips=tips, setup=[{"script": s} for s in (setup or [])]))
    solutions[id] = solution


def check(type, **kw):
    return dict(type=type, **kw)


def content(path, value, **kw):
    return check("content", path=path, value=value, **kw)


base = "/home/learner/lab"


def write_file(path, text):
    return f"printf %s {shlex.quote(text)} > {shlex.quote(path)}"

add("find-your-feet", "Find your feet", f"Find your current directory with `pwd`. Explore `{base}` with `ls -la`. Save the absolute path of your home directory to `{base}/home-path.txt`.", [("Save your home path", [content(f"{base}/home-path.txt", "/home/learner")])], ["`pwd` prints the current directory.", "`>` sends command output into a file."], f"printf '/home/learner\\n' > {base}/home-path.txt")
add("make-directories", "A place for everything", f"Create a project tree: `{base}/project/src` and `{base}/project/docs`.", [("Create the source directory", [check("path", path=f"{base}/project/src", kind="directory")]), ("Create the documentation directory", [check("path", path=f"{base}/project/docs", kind="directory")])], ["`mkdir -p` creates missing parent directories."], f"mkdir -p {base}/project/{{src,docs}}")
add("copy-and-move", "Copy, move, keep", f"Copy `{base}/inputs/message.txt` to `{base}/copied.txt`. Create `{base}/renamed.txt` containing the same message, using `mv` to practice renaming.", [("Keep a copy of the message", [content(f"{base}/copied.txt", "Linux is a place to explore")]), ("Save the renamed message", [content(f"{base}/renamed.txt", "Linux is a place to explore")])], ["`cp` duplicates files; `mv` renames or relocates them."], f"cp {base}/inputs/message.txt {base}/copied.txt; cp {base}/inputs/message.txt {base}/temporary.txt; mv {base}/temporary.txt {base}/renamed.txt")
add("remove-safely", "Clean up carefully", f"Remove only `{base}/cleanup/obsolete.txt` and preserve `{base}/cleanup/keep.txt`.", [("Remove the obsolete file", [check("path", path=f"{base}/cleanup/obsolete.txt", kind="absent")]), ("Keep the useful file unchanged", [content(f"{base}/cleanup/keep.txt", "keep me")])], ["Check a path with `ls` before removing it.", "Deleted files in this lab have no recycle bin."], f"rm {base}/cleanup/obsolete.txt", [f"install -d -o learner -g learner {base}/cleanup; printf 'obsolete' > {base}/cleanup/obsolete.txt; printf 'keep me' > {base}/cleanup/keep.txt; chown -R learner:learner {base}/cleanup"])
add("hidden-files", "What is hidden?", f"Create `{base}/.practice-config` containing `theme=green`. Use `ls -a` to find it.", [("Create the hidden configuration", [content(f"{base}/.practice-config", "theme=green")])], ["A leading dot hides a file from a plain `ls`."], f"printf 'theme=green\\n' > {base}/.practice-config")
add("links", "One file, another doorway", f"Create a symbolic link `{base}/message-link` pointing to `{base}/inputs/message.txt`.", [("Create a readable symbolic link", [check("path", path=f"{base}/message-link", kind="symlink"), content(f"{base}/message-link", "Linux is a place to explore")])], ["Read `man ln` and look for the symbolic link option."], f"ln -s {base}/inputs/message.txt {base}/message-link")
add("read-manuals", "Read the manual", f"Explore `man ls`, `info coreutils`, and `help cd`. Write a short note at `{base}/manuals.txt` containing the terms `man`, `info`, and `help`.", [("Record three ways to get help", [content(f"{base}/manuals.txt", word) for word in ["man", "info", "help"]])], ["Press `q` to leave a manual page.", "Bash built-ins such as `cd` are documented by `help`."], f"printf 'man ls; info coreutils; help cd\\n' > {base}/manuals.txt")
for editor, title in [("vi", "Meet vi"), ("vim", "A little Vim"), ("nano", "Keep it simple with nano"), ("gedit", "A graphical note with gedit")]:
    add(f"editor-{editor}", title, f"Use `{editor} {base}/{editor}-note.txt` to create a note containing `Learning with {editor}`. Save the file and return to the terminal. Evaluation checks the saved result, not which editor you used.", [(f"Save your {editor} note", [content(f"{base}/{editor}-note.txt", f"Learning with {editor}")])], ["In vi/Vim: press `i`, type, press Esc, then type `:wq` and Enter." if editor in ("vi", "vim") else "In nano: Ctrl+O saves and Ctrl+X exits." if editor == "nano" else "Gedit opens in this same desktop. Save with Ctrl+S; use `&` to keep the shell available."], f"printf 'Learning with {editor}\\n' > {base}/{editor}-note.txt")
add("grep-logs", "Find the signal", f"Read `{base}/inputs/app.log`. Save only the lines containing `ERROR` to `{base}/errors.log`.", [("Keep the error lines", [content(f"{base}/errors.log", "ERROR disk full"), content(f"{base}/errors.log", "ERROR timeout")]), ("Exclude informational lines", [check("command", script=f"! grep -q INFO {base}/errors.log")])], ["`grep` selects matching lines; `>` saves them."], f"grep ERROR {base}/inputs/app.log > {base}/errors.log")
add("sort-and-count", "Order out of repetition", f"Sort and deduplicate `{base}/inputs/fruit.txt` into `{base}/unique-fruit.txt`. Save the number of unique fruits to `{base}/fruit-count.txt`.", [("Save sorted unique fruit", [content(f"{base}/unique-fruit.txt", "apple\nbanana\npear\n", match="exact")]), ("Count the unique fruit", [content(f"{base}/fruit-count.txt", "3")])], ["Pipes connect commands.", "Explore `sort`, `uniq`, and `wc -l`."], f"sort -u {base}/inputs/fruit.txt > {base}/unique-fruit.txt; wc -l < {base}/unique-fruit.txt > {base}/fruit-count.txt")
add("replace-text", "A small transformation", f"Replace every `old` with `new` in `{base}/inputs/settings.txt` and save the result as `{base}/settings.txt`.", [("Transform both settings", [content(f"{base}/settings.txt", "name=new\nmode=new\n", match="exact")])], ["`sed` can substitute text without changing the input file."], f"sed 's/old/new/g' {base}/inputs/settings.txt > {base}/settings.txt")
add("find-files", "Find your files", f"Use `find` to locate `.txt` files under `{base}/inputs`. Save the list to `{base}/found-files.txt`.", [("Record matching input paths", [content(f"{base}/found-files.txt", f"{base}/inputs/message.txt"), content(f"{base}/found-files.txt", f"{base}/inputs/fruit.txt")])], ["Quote patterns so the shell does not expand them first: `'*.txt'`."], f"find {base}/inputs -name '*.txt' > {base}/found-files.txt")
add("private-file", "Keep it private", f"Create `{base}/private.txt` and set its permissions to `600`.", [("Only the owner can read or write", [check("permissions", path=f"{base}/private.txt", mode="600")])], ["Read `man chmod`.", "Read, write, execute have values 4, 2, and 1."], f"touch {base}/private.txt; chmod 600 {base}/private.txt")
add("shared-directory", "A shared space", f"Create `{base}/shared` with permissions `2770`: owner/group full access, no access for others, and setgid.", [("Set the shared-directory permissions", [check("path", path=f"{base}/shared", kind="directory"), check("permissions", path=f"{base}/shared", mode="2770")])], ["The leading `2` sets setgid on a directory."], f"mkdir -p {base}/shared; chmod 2770 {base}/shared")
add("create-user", "Welcome a new user", "Create a user named `labalex` with home directory `/home/labalex` and login shell `/bin/bash`.", [("Create the account with its home and shell", [check("user", name="labalex", home="/home/labalex", shell="/bin/bash"), check("path", path="/home/labalex", kind="directory")])], ["Use `sudo` for account administration.", "Explore `useradd -m -s`."], "sudo useradd -m -s /bin/bash labalex")
add("create-group", "A team of your own", "Create a group called `labteam`.", [("Create the team group", [check("group", name="labteam")])], ["Group definitions can be inspected with `getent group`."], "sudo groupadd labteam")
add("group-membership", "Join the team", "Add `labmember` to the supplementary group `labpractice`. These accounts are prepared for you and are independent of the other exercises.", [("Add the supplementary membership", [check("membership", user="labmember", group="labpractice")])], ["Use `usermod -aG` to append rather than replace supplementary groups.", "Inspect membership with `id labmember`."], "sudo usermod -aG labpractice labmember", ["groupadd labpractice; useradd -m -s /bin/bash labmember"])
add("file-ownership", "Who owns this?", f"Create `{base}/owned.txt` owned by user `learner` and group `labowners`. The group already exists.", [("Assign the owner and group", [check("ownership", path=f"{base}/owned.txt", owner="learner", group="labowners")])], ["Use `chown user:group file`.", "Check your result with `ls -l`."], f"touch {base}/owned.txt; sudo chown learner:labowners {base}/owned.txt", ["groupadd labowners"])
add("remove-user", "An account's last day", "Remove the pre-created disposable account `labtemporary`. Other accounts must remain available.", [("Remove the disposable user", [check("user", name="labtemporary", exists=False)]), ("Preserve the learner account", [check("user", name="learner")])], ["Explore `userdel`; account changes require sudo."], "sudo userdel -r labtemporary", ["useradd -m labtemporary"])
add("process-snapshot", "What's running?", f"Use `ps` to save a process listing into `{base}/processes.txt`. Include command names so the listing contains `supervisord`.", [("Save a useful process snapshot", [content(f"{base}/processes.txt", "supervisord")])], ["Try `ps aux` or `ps -ef`."], f"ps aux > {base}/processes.txt")
add("background-job", "Let it run in the background", "Start a `sleep` process as `learner` that remains running for a few minutes. Evaluate before it finishes.", [("Keep a learner-owned sleep process running", [check("process", name="sleep", user="learner")])], ["Append `&` to run a command in the background.", "Use `sleep 600 &`, then inspect `jobs` and `ps`."], "nohup sleep 600 >/tmp/lab-sleep.log 2>&1 &")
add("network-interfaces", "Meet your network", f"Use `ip` to list network interfaces and save them to `{base}/interfaces.txt`. Include the loopback interface.", [("Record loopback interface information", [content(f"{base}/interfaces.txt", "lo:")])], ["`ip address` shows interfaces and addresses.", "This container's network is separate from Windows."], f"ip address > {base}/interfaces.txt")
add("local-hostname", "A name for this machine", f"Save this environment's hostname to `{base}/hostname.txt`. Inspect `/etc/hosts` to see local name mappings.", [("Record the hostname", [content(f"{base}/hostname.txt", "linux-lab")])], ["`hostname` works without Internet access."], f"hostname > {base}/hostname.txt")
add("package-inventory", "Know your tools", f"Use `dpkg-query` to record information about the installed `nano` package in `{base}/package-info.txt`.", [("Nano is installed", [check("package", name="nano")]), ("Record its package name", [content(f"{base}/package-info.txt", "nano")])], ["`dpkg-query -W nano` queries an installed package without downloading anything."], f"dpkg-query -W nano > {base}/package-info.txt")
add("archive", "Pack it up", f"Create `{base}/notes.tar.gz` containing `message.txt` from the inputs folder. Preserve the original file.", [("Create a readable gzip archive with the message", [check("command", script=f"tar -tzf {base}/notes.tar.gz | grep -Eq '(^|/)message\\.txt$'")]), ("Keep the original message", [check("path", path=f"{base}/inputs/message.txt", kind="file")])], ["`tar -czf` creates a gzip-compressed archive.", "The `-C` option chooses the input directory."], f"tar -czf {base}/notes.tar.gz -C {base}/inputs message.txt")
add("first-script", "Your first shell script", f"Create executable `{base}/greet.sh` that prints `Hello, Linux!` when run.", [("Make the script executable", [check("permissions", path=f"{base}/greet.sh", mode="755")]), ("Print the greeting", [check("command", script=f"{base}/greet.sh", user="learner", stdout_contains="Hello, Linux!")])], ["Start with `#!/bin/bash`.", "Use `chmod 755` to make your script executable."], write_file(f"{base}/greet.sh", '#!/bin/bash\nprintf "Hello, Linux!\\n"\n') + f"; chmod 755 {base}/greet.sh")
add("script-arguments", "Make it personal", f"Create `{base}/welcome.sh`. Running `bash {base}/welcome.sh Ada` must print `Welcome, Ada`. Passing `Linus` must print `Welcome, Linus`.", [("Use the first argument", [check("command", script=f"bash {base}/welcome.sh Ada", stdout_contains="Welcome, Ada"), check("command", script=f"bash {base}/welcome.sh Linus", stdout_contains="Welcome, Linus")])], ["The first argument is available as `$1`.", "Use double quotes when expanding variables."], write_file(f"{base}/welcome.sh", '#!/bin/bash\nprintf "Welcome, %s\\n" "$1"\n'))

course = Course.model_validate(dict(schema_version=1, id="linux-foundations", version="1.0", title="Linux Foundations", description="Build confidence with files, editors, permissions, users, groups, and everyday Linux commands.", setup=[dict(script=f"install -d -o learner -g learner {base} {base}/inputs\nprintf 'Linux is a place to explore\\n' > {base}/inputs/message.txt\nprintf 'INFO start\\nERROR disk full\\nINFO waiting\\nERROR timeout\\n' > {base}/inputs/app.log\nprintf 'pear\\napple\\nbanana\\napple\\n' > {base}/inputs/fruit.txt\nprintf 'name=old\\nmode=old\\n' > {base}/inputs/settings.txt\nchown -R learner:learner {base}")], exercises=exercises))
assert len(course.exercises) == 30
(ROOT / "courses").mkdir(exist_ok=True)
(ROOT / "courses" / "foundations.yaml").write_text(course_yaml(course), encoding="utf-8")
(ROOT / "courses" / "foundations-solutions.json").write_text(json.dumps(solutions, indent=2), encoding="utf-8")
print(f"Wrote {len(course.exercises)} exercises")
